const tHrs=s=>{s=String(s||"");let m=s.match(/(\d+)\s*x\s*(\d+)/i);if(m)return Math.min(100,+m[1]*+m[2]);m=s.match(/(\d+)\s*hrs?/i);if(m)return Math.min(100,+m[1]);const n=(s.match(/\d+/g)||[]).map(Number).filter(x=>x>0&&x<=100);return n.length>1?Math.round((n[0]+n[1])/2):n[0]||50};
function tPay(rate,perDiem,h,days){h=Math.max(0,Math.min(100,+h||0));const st=Math.min(h,40)*rate,ot=Math.max(h-40,0)*rate*1.5,wage=st+ot,tax=Math.round(wage*.22),pd=(perDiem||0)*(days==null?7:days);return{st:Math.round(st),ot:Math.round(ot),wage:Math.round(wage),tax,pd:Math.round(pd),gross:Math.round(wage+pd),net:Math.round(wage-tax+pd)}}
