 const bring=[...(c.tools?c.tools.split(/,|;/).map(s=>s.trim()).filter(Boolean):["Standard hand tools"]),"Current license card"+(c.lstate?" ("+c.lstate+" or reciprocal)":""),"Photo ID and safety card (OSHA 10/30)","Hard hat, safety glasses, steel or composite toes"];
