function tCal(t,u){const out=[],now=new Date();now.setHours(0,0,0,0);now.setDate(now.getDate()-((now.getDay()+6)%7));const avail=t.availNow?0:new Date(t.availDate).getTime();
 const booked=(DB.tcalls||[]).filter(c=>c.apps.some(a=>a.uid===u.id&&a.status==="hired"));for(let i=0;i<12;i++){const d=new Date(now);d.setDate(d.getDate()+i*7);const ds=d.getTime(),de=ds+7*864e5;
  const b=booked.find(c=>{const s=new Date(c.start).getTime(),e=s+c.weeks*7*864e5;return de>s&&ds<e});const st=b?"busy":de>avail?"free":"busy";
  out.push(`<div class="t6cal-w ${st}" title="${b?"Booked: "+esc(b.title):st==="free"?"Available":"Not available"}"><small>${d.toLocaleDateString("en-US",{month:"short"})}</small><b>${d.getDate()}</b></div>`)}
 return`<div class="t6cal" role="img" aria-label="Availability for the next 12 weeks: ${t.availNow?"available now":"available from "+fmtD(t.availDate)}">${out.join("")}</div><p class="small muted t6cal-k"><i class="free"></i>Available <i class="busy"></i>Booked or not available · weeks starting Monday</p>`}
