function tMsgModal(who,cid){const m=me(),u=U(who);if(!m||!u)return;const th=(DB.msgs||[]).filter(x=>(x.a===m.id&&x.b===who)||(x.b===m.id&&x.a===who)).slice(-6);const c=TC(cid);
 modal(`<h2 id="mtitle">Message ${esc(nameOf(u))}</h2><p class="muted small">${c?"About: "+esc(c.title):""}</p><div class="t6thread">${th.length?th.map(x=>`<p class="${x.from===m.id?"me":""}">${esc(x.text)}</p>`).join(""):`<p class="muted small t6none">No messages yet. Say hi and share next steps.</p>`}</div><form id="tmsgF" class="form"><label class="sr" for="tmsgTxt">Message</label><textarea id="tmsgTxt" rows="3" placeholder="Hi ${esc(nameOf(u).split(" ")[0])}, you're on our shortlist. Can you start ${c?fmtD(c.start):"soon"}?"></textarea><div class="actions"><a class="btn ghost" href="${href("msgs",who)}">Open full thread</a><button class="btn primary" id="tmsgGo">${I("send",16)}Send</button></div></form>`);
 document.getElementById("tmsgF").onsubmit=e=>{e.preventDefault();const t=document.getElementById("tmsgTxt").value;const r=A.send(who,t);if(r&&r.ok){closeModal();toast("Message sent to "+nameOf(u))}else act(r)};document.querySelector("#modal a.btn.ghost").onclick=closeModal}
VIEWS.tdash=(p,q)=>{const m=me();if(!m)return`<section class="v2page">${UH(I("kanban",14)+" Travel work","Traveler dashboard","Track applications, saved calls and alerts, or manage your applicant pipeline.")}<div class="wrap narrow">${empty("kanban","Sign in to see your dashboard","Travelers track applications here. Contractors manage applicants here.",`<a class="btn primary" href="${href("signup",null,{next:"/tdash"})}">Sign in</a>`)}</div></section>`;
 if(canPostT(m)&&q.view!=="me")return tPipeline(m,(DB.tcalls||[]).filter(c=>c.by===m.id),q);return tMine(m,q)};
function tPipeline(m,calls,q){const head=UH(I("kanban",14)+" Travel work","Applicant pipeline","Move travelers from applied to shortlisted to hired. Message anyone in one tap.",`<div class="row wrapr"><a class="btn primary" href="${href("newtravel")}">${I("plus",16)}Post a traveler call</a>${m.trav?`<a class="btn" href="${href("tdash",null,{view:"me"})}">My applications</a>`:""}</div>`);
 if(!calls.length)return`<section class="v2page">${head}<div class="wrap"><div class="t6empty big">${I("kanban",40)}<b>No traveler calls yet</b><small>Post your first call with rate, per diem and license. Applicants land here in columns you can drag between.</small><a class="btn primary" href="${href("newtravel")}">${I("plus",16)}Post a traveler call</a></div></div></section>`;
 const c=TC(q.call)&&TC(q.call).by===m.id?TC(q.call):calls[0];const col=(st,label,ic,hint)=>{const L=c.apps.filter(a=>a.status===st);return`<section class="t6col c-${st}" data-col="${st}" id="col-${st}" aria-label="${label}"><header><span>${I(ic,16)}${label}</span><em>${L.length}</em></header><div class="t6col-b">${L.map(a=>tKCard(c,a,st)).join("")||`<p class="t6col-e">${hint}</p>`}</div></section>`};
 const dec=c.apps.filter(a=>a.status==="declined"||a.status==="withdrawn"),hiredN=c.apps.filter(a=>a.status==="hired").length;
 return`<section class="v2page t6pipe" data-call="${c.id}">${head}<div class="wrap"><div class="t6calls" role="tablist" aria-label="Your calls">${calls.map(x=>{const n=x.apps.filter(a=>a.status==="pending"||a.status==="short").length;return`<a role="tab" aria-selected="${x.id===c.id}" class="${x.id===c.id?"on":""}" href="${href("tdash",null,{call:x.id})}"><b>${esc(x.title)}</b><small>${esc(x.loc)}, ${esc(x.state)} · ${x.apps.filter(a=>a.status==="hired").length}/${x.need} hired${n?` · <em>${n} active</em>`:""}</small></a>`}).join("")}</div>
 <div class="t6pipe-h card"><div><h2>${esc(c.title)}</h2><p class="muted small">${tMoney(c.rate)}/hr + ${tMoney(c.perDiem)}/day · starts ${fmtD(c.start)} · ${c.status==="open"?"open":"filled"}</p></div><div class="t6spots big"><i style="--f:${(hiredN/c.need*100).toFixed(0)}%"></i><span><b>${hiredN}</b> of ${c.need} hired</span></div><div class="row wrapr"><a class="btn sm ghost" href="${href("tcall",c.id)}">View call</a><a class="btn sm" href="${href("travel",null,{tab:"travelers",state:c.state})}">${I("users",14)}Invite travelers</a></div></div>
 <div class="t6kan" id="tKan">${col("pending","Applied","send","New applicants land here.")}${col("short","Shortlisted","star","Tap Shortlist, or drag a card here, to keep someone in the running.")}${col("hired","Hired","check","Hire to fill a spot. They're notified instantly.")}</div>
 ${dec.length?`<details class="t6dec card"><summary>Declined or withdrawn (${dec.length})</summary>${dec.map(a=>{const u=U(a.uid);return u?`<div class="t6dec-r">${avatar(u,"sm")}<span>${esc(nameOf(u))}</span><small class="muted">${a.status}</small>${a.status==="declined"?`<button class="btn sm ghost" data-stage="${u.id}:pending">Restore</button>`:""}</div>`:""}).join("")}</details>`:""}</div></section>`}
function tKCard(c,a,st){const u=U(a.uid);if(!u)return"";const t=u.trav||{lic:[],yrs:0},r=u.trav?tTR(u):null;
 const btns=st==="pending"?`<button class="btn sm" data-stage="${u.id}:short">${I("star",14)}Shortlist</button><button class="btn sm primary" data-stage="${u.id}:hired">Hire</button>`:st==="short"?`<button class="btn sm primary" data-stage="${u.id}:hired">${I("check",14)}Hire</button><button class="btn sm ghost" data-stage="${u.id}:pending">Back</button>`:"";
 return`<article class="t6k-card" draggable="true" data-uid="${u.id}" aria-label="${esc(nameOf(u))}"><div class="t6k-h">${avatar(u,"sm")}<div><a href="${href("traveler",u.id)}"><b>${esc(nameOf(u))}</b></a><small>${tLic(t)} · ${t.yrs} yrs${r?" · ★ "+tRatAvg(r).toFixed(1):""}</small></div>${st!=="hired"?`<button class="t6k-x" data-stage="${u.id}:declined" aria-label="Decline ${esc(nameOf(u))}" title="Decline">${I("x",14)}</button>`:`<span class="t6k-ok">${I("check",14)}</span>`}</div>${a.note?`<p class="t6k-note">“${esc(a.note)}”</p>`:""}<div class="t6k-meta">${t.availNow?`<span class="t6b t6b-soon">Available now</span>`:t.availDate?`<span class="t6b">From ${fmtD(t.availDate)}</span>`:""}${a.invited?`<span class="t6b">Invited</span>`:""}<span class="muted small">${ago(a.date)}</span></div>
 <div class="t6k-a"><button class="btn sm ghost" data-tmsg="${u.id}" aria-label="Message ${esc(nameOf(u))}">${I("chat",14)}Message</button>${btns}</div></article>`}
function tMine(m,q){const apps=(DB.tcalls||[]).map(c=>({c,a:c.apps.find(a=>a.uid===m.id&&a.status!=="withdrawn")})).filter(x=>x.a).sort((x,y)=>y.a.date-x.a.date);const inv=(DB.tcalls||[]).filter(c=>c.invites.includes(m.id)&&!c.apps.some(a=>a.uid===m.id&&a.status!=="withdrawn")&&c.status==="open");const saved=(m.tsaved||[]).map(TC).filter(Boolean);const al=m.talerts||[];
 const cnt=k=>apps.filter(x=>x.a.status===k).length;const step=s=>{const i=s==="hired"?2:s==="short"?1:0;return`<ol class="t6step ${s==="declined"?"no":""}" aria-label="Status">${["Applied","Shortlisted","Hired"].map((l,k)=>`<li class="${s!=="declined"&&k<=i?"on":""}">${l}</li>`).join("")}</ol>`};
 const head=UH(I("kanban",14)+" Travel work","Your traveler dashboard","Applications, invites, saved calls and alerts in one place.",`<div class="row wrapr"><a class="btn primary" href="${href("travel")}">${I("search",16)}Find calls</a><a class="btn" href="${href(m.trav?"traveler":"travme",m.trav?m.id:null)}">${I("user",16)}${m.trav?"My profile":"Create profile"}</a></div>`);
 return`<section class="v2page t6mine">${head}<div class="wrap"><div class="t6mk"><div><b>${apps.length}</b><span>Applications</span></div><div><b>${cnt("short")}</b><span>Shortlisted</span></div><div><b>${cnt("hired")}</b><span>Hired</span></div><div><b>${saved.length}</b><span>Saved calls</span></div></div>
 ${inv.length?`<section class="t6sec"><h2>${I("bell",20)}Invites <span class="badge">${inv.length}</span></h2><div class="t6apps">${inv.map(c=>`<div class="card t6app-r">${tLogo(U(c.by))}<div><a href="${href("tcall",c.id)}"><b>${esc(c.title)}</b></a><small class="muted">${esc(nameOf(U(c.by)))} invited you · ${esc(c.loc)}, ${esc(c.state)} · ${tMoney(c.rate)}/hr</small></div>${tApplyBtn(c,m)}</div>`).join("")}</div></section>`:""}
 <section class="t6sec" id="myApps"><h2>${I("send",20)}Applications</h2>${apps.length?`<div class="t6apps">${apps.map(({c,a})=>`<div class="card t6app-r">${tLogo(U(c.by))}<div><a href="${href("tcall",c.id)}"><b>${esc(c.title)}</b></a><small class="muted">${esc(nameOf(U(c.by)))} · ${esc(c.loc)}, ${esc(c.state)} · applied ${ago(a.date)}</small>${step(a.status)}</div><span class="t6app-s s-${a.status}">${a.status==="pending"?"Applied":a.status==="short"?"Shortlisted":a.status==="hired"?"Hired":"Not selected"}</span></div>`).join("")}</div>`:`<div class="t6empty">${I("send",28)}<b>No applications yet</b><small>Apply in one tap from any traveler call. Your status updates here.</small><a class="btn primary sm" href="${href("travel")}">Browse calls</a></div>`}</section>
 <section class="t6sec" id="mySaved"><h2>${I("bookmark",20)}Saved calls</h2>${saved.length?`<div class="t5list">${saved.map(c=>tCallCard(c,m)).join("")}</div>`:`<div class="t6empty">${I("bookmark",28)}<b>Nothing saved</b><small>Tap the bookmark on any call to keep it here.</small></div>`}</section>
 <section class="t6sec" id="myAlerts"><h2>${I("bell",20)}Alerts</h2>${al.length?`<div class="t6alerts">${al.map(a=>`<div class="card t6al"><span>${I("bell",16)}${[a.type||"Any type",a.state?"in "+a.state:"any state",a.minRate?"$"+a.minRate+"+/hr":""].filter(Boolean).join(" · ")}</span><button class="btn sm ghost" data-delal="${a.id}" aria-label="Delete alert">${I("x",14)}Delete</button></div>`).join("")}</div>`:`<div class="t6empty">${I("bell",28)}<b>No alerts</b><small>For example: calls in TX paying $40+/hr. Add one below or from the board filters.</small></div>`}
 <form class="t6alf card" id="tAlF"><b>New alert</b>${tSel("al-state","State",T_STATES,"","Any state")}${tSel("al-type","Type",T_TYPES,"","Any type")}<label class="t5f" for="al-rate"><span>Min $/hr</span><input id="al-rate" name="minRate" type="number" min="0" max="250" inputmode="decimal" placeholder="40"></label><button class="btn primary" id="alGo">${I("bell",16)}Add alert</button></form></section></div></section>`}
AFTER.tdash=()=>{tBind();const pipe=document.querySelector(".t6pipe"),callId=pipe&&pipe.dataset.call;const rer=()=>{const y=scrollY;render();scrollTo(0,y)};
 document.querySelectorAll("[data-stage]").forEach(b=>b.onclick=()=>{const[u,s]=b.dataset.stage.split(":");act(A.stageTravel(callId,u,s),rer)});document.querySelectorAll("[data-tmsg]").forEach(b=>b.onclick=()=>tMsgModal(b.dataset.tmsg,callId));
 document.querySelectorAll(".t6k-card").forEach(k=>{k.ondragstart=e=>{e.dataTransfer.setData("text/plain",k.dataset.uid);k.classList.add("drag")};k.ondragend=()=>k.classList.remove("drag")});document.querySelectorAll(".t6col").forEach(c=>{c.ondragover=e=>{e.preventDefault();c.classList.add("over")};c.ondragleave=()=>c.classList.remove("over");c.ondrop=e=>{e.preventDefault();c.classList.remove("over");const u=e.dataTransfer.getData("text/plain");u&&act(A.stageTravel(callId,u,c.dataset.col),rer)}});
 document.querySelectorAll("[data-delal]").forEach(b=>b.onclick=()=>act(A.delAlert(b.dataset.delal),rer));const f=document.getElementById("tAlF");f&&(f.onsubmit=e=>{e.preventDefault();const o=readForm(f);act(A.setAlert({state:o.state,type:o.type,minRate:o.minRate}),rer)})};
