VIEWS.traveling=()=>{const calls=(DB.tcalls||[]).filter(c=>c.status==="open"),top=calls.slice().sort((a,b)=>tNet(b)-tNet(a)).slice(0,3),ex=tPay(46,120,60);
 const faq=[["Is it free for travelers?","Yes. Your profile, applying and invites are free, always. Contractors pay the flat $20/mo Pro plan. Nobody pays lead or hiring fees."],["How is the take-home estimate calculated?","Hourly wages with time-and-a-half after 40 hours, minus about 22% withheld, plus per diem for 7 days. It's an estimate for comparing calls. Real pay depends on your taxes, the contractor's payroll and the hours actually worked."],["Is per diem taxable?","Per diem is usually not taxed when you keep a tax home and travel away from it for work. Rules depend on your situation, so confirm with a tax professional."],["Do I need a license in every state?","Usually you need a license or reciprocity in the job's state. Every call lists the license required and the reciprocity the contractor accepts."],["Union or non-union?","Both. Each call shows union status and IBEW local where relevant, and you can filter for it."],["What do contractors see?","Your traveler profile: licenses, states, availability, specialties and safety cards. Your email and phone stay private until you share them."]];
 return`<section class="t6land"><header class="t6l-hero"><img src="/img/tr-road.webp" alt="Pickup truck on an open highway" decoding="async"><div class="wrap"><span class="t6l-k">${I("road",16)}For traveling electricians</span><h1>Make more<br>on the road.</h1><p>Per diem calls on data centers, plants, solar farms and hospitals. Rate, per diem and license on every listing. Apply in one tap, free.</p><div class="row wrapr"><a class="btn primary lg" href="${href("travme")}">${I("user",18)}List yourself free</a><a class="btn lg t6l-ghost" href="${href("travel")}">Browse ${calls.length} calls ${I("arrow",16)}</a></div></div></header>
 <section class="wrap t6l-ex" aria-label="Example pay"><div class="t6l-exc card"><span class="t6l-tag">Example, not a guarantee</span><div><b>${tMoney(46)}</b><small>per hour</small></div><span class="op">+</span><div><b>${tMoney(120)}</b><small>per diem / day</small></div><span class="op">×</span><div><b>60</b><small>hrs / week</small></div><span class="op">≈</span><div class="hl"><b>~${tMoney(ex.net)}</b><small>est. weekly take-home</small></div></div><p class="small muted">Example values. 1.5× after 40 hrs, about 22% withheld from wages, per diem 7 days.</p></section>
 <section class="wrap t6l-how"><div class="ehead"><span class="kick">How it works</span><h2>Three steps to your next call.</h2></div><div class="t6l-steps">${[["tr-wire","List your profile","Licenses, states you'll work, availability and specialties. About two minutes, free."],["tr-panel","Apply or get invited","One tap sends your profile. Contractors can also find you and invite you directly."],["tr-solar","Hit the road","Get hired, see the start date and what to bring, and message the foreman before you mobilize."]].map(([img,h,p],i)=>`<article class="card"><img src="/img/${img}.webp" alt="" loading="lazy"><div><span class="t6l-n">${i+1}</span><h3>${h}</h3><p class="muted">${p}</p></div></article>`).join("")}</div></section>
 <section class="wrap t6l-top"><div class="t6l-toph"><div><span class="kick">Top paying right now</span><h2>Calls travelers are applying to.</h2></div><a class="btn" href="${href("travel",null,{sort:"pay"})}">See all ${I("arrow",16)}</a></div><div class="t5list">${top.map(c=>tCallCard(c,me())).join("")}</div></section>
 <section class="wrap t6l-why"><div class="t6l-why-g"><img src="/img/tr-solar2.webp" alt="Technician installing solar panels" loading="lazy"><div><span class="kick">Why travelers use __BRAND__</span><h2>No recruiters in the middle.</h2><ul class="t6l-l">${[["dollar","Pay up front","Rate, per diem and estimated take-home on every call."],["badge","License clarity","Required license and accepted reciprocity listed before you apply."],["bell","Alerts that matter","“Calls in TX paying $40+” straight to your notifications."],["lock","Your contact stays private","Contractors message you in-app until you choose to share your number."]].map(([i,h,p])=>`<li><span>${I(i,20)}</span><div><b>${h}</b><p class="muted">${p}</p></div></li>`).join("")}</ul></div></div></section>
 <section class="wrap t6l-faq"><div class="ehead"><span class="kick">FAQ</span><h2>Questions travelers ask.</h2></div><div class="t6faq">${faq.map(([q,a])=>`<details><summary>${q}${I("plus",18)}</summary><p>${a}</p></details>`).join("")}</div></section>
 <section class="wrap"><div class="t6l-cta"><div><h2>Your next call is already posted.</h2><p>List free in two minutes. Turn on Available now and contractors see you first.</p></div><a class="btn primary lg" href="${href("travme")}">Get started free ${I("arrow",16)}</a></div></section></section>`};
